window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-23be041a5085e121"]={"versions": [{"id": "FIG-23be041a5085e121", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt der AUTOSAR-ECU-Konfigurationsparameter (ECUC). Das Diagramm stellt die strukturelle Zerlegung des Konfigurationscontainers <code>CsmPrimitives</code> innerhalb des Crypto Service Managers (CSM, AUTOSAR Classic Platform) in kryptografische Primitive-Konfigurationscontainer dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der übergeordnete Konfigurationscontainer:</p>\n<ul class=\"fig-list\"><li><code>CsmPrimitives: EcucParamConfContainerDef</code> (Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>).\n</li></ul>\n<p class=\"fig-p\">Über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+subContainer</code> sind folgende Sub-Container (alle vom Typ <code>EcucParamConfContainerDef</code>, jeweils mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>) untergeordnet:</p>\n<ul class=\"fig-list\"><li><code>CsmHash</code>\n</li><li><code>CsmMacGenerate</code>\n</li><li><code>CsmMacVerify</code>\n</li><li><code>CsmEncrypt</code>\n</li><li><code>CsmDecrypt</code>\n</li><li><code>CsmAEADEncrypt</code>\n</li><li><code>CsmAEADDecrypt</code>\n</li><li><code>CsmSignatureGenerate</code>\n</li><li><code>CsmSignatureVerify</code>\n</li><li><code>CsmSecureCounter</code>\n</li><li><code>CsmRandomGenerate</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations- und Metamodell. Es sind keine dynamischen Interaktionen, Zustandsübergänge oder Aufrufsequenzen dargestellt. Die Beziehungen definieren die statische Schachtelungshierarchie zur Parametrierung des CSM zur Entwurfs- und Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die ECU-Konfiguration des Moduls CSM. Eine Instanz von <code>CsmPrimitives</code> kann optional (<code>0..1</code>) Container für die jeweiligen kryptografischen Basisoperationen enthalten. BSW-Generatoren und Konfigurationseditoren müssen diese Container-Definitionen und Kardinalitäten validieren, um die erforderlichen CSM-Dienste zu konfigurieren.</p>"}, {"id": "FIG-bc747f7e846ce84c", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt der AUTOSAR-ECU-Konfigurationsparameter (ECUC). Das Diagramm stellt die strukturelle Zerlegung des Konfigurationscontainers <code>CsmPrimitives</code> innerhalb des Crypto Service Managers (CSM, AUTOSAR Classic Platform) in kryptografische Primitive-, Schlüssel- und Zertifikatsverwaltungs-Konfigurationscontainer dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der übergeordnete Konfigurationscontainer:</p>\n<ul class=\"fig-list\"><li><code>CsmPrimitives: EcucParamConfContainerDef</code> (Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>).\n</li></ul>\n<p class=\"fig-p\">Über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+subContainer</code> sind folgende Sub-Container (alle vom Typ <code>EcucParamConfContainerDef</code>, jeweils mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>) untergeordnet:</p>\n<ul class=\"fig-list\"><li><code>CsmHash</code>\n</li><li><code>CsmMacGenerate</code>\n</li><li><code>CsmMacVerify</code>\n</li><li><code>CsmEncrypt</code>\n</li><li><code>CsmDecrypt</code>\n</li><li><code>CsmAEADEncrypt</code>\n</li><li><code>CsmAEADDecrypt</code>\n</li><li><code>CsmSignatureGenerate</code>\n</li><li><code>CsmSignatureVerify</code>\n</li><li><code>CsmRandomGenerate</code>\n</li><li><code>CsmJobKeySetValid</code>\n</li><li><code>CsmJobRandomSeed</code>\n</li><li><code>CsmJobKeyDerive</code>\n</li><li><code>CsmJobKeyGenerate</code>\n</li><li><code>CsmJobKeyExchangeCalcPubVal</code>\n</li><li><code>CsmJobKeyExchangeCalcSecret</code>\n</li><li><code>CsmJobCertificateParse</code>\n</li><li><code>CsmJobCertificateVerify</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations- und Metamodell. Es sind keine dynamischen Interaktionen, Zustandsübergänge oder Aufrufsequenzen dargestellt. Die Beziehungen definieren die statische Schachtelungshierarchie zur Parametrierung des CSM zur Entwurfs- und Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die ECU-Konfiguration des Moduls CSM. Eine Instanz von <code>CsmPrimitives</code> kann optional (<code>0..1</code>) Container für die jeweiligen kryptografischen Basisoperationen sowie für Schlüsselmanagement- und Zertifikatsprüfoperationen enthalten. BSW-Generatoren und Konfigurationseditoren müssen diese Container-Definitionen und Kardinalitäten validieren, um die entsprechenden CSM-Dienste zu konfigurieren.</p>"}], "trans": [{"from": "FIG-23be041a5085e121", "to": "FIG-bc747f7e846ce84c", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Container <code>CsmSecureCounter</code> entfernt.\n</li><li>Neue Sub-Container unter <code>CsmPrimitives</code> ergänzt (jeweils Typ <code>EcucParamConfContainerDef</code>, Multiplizität <code>0..1</code> via <code>+subContainer</code>):\n<ul class=\"fig-list\"><li><code>CsmJobKeySetValid</code>\n</li><li><code>CsmJobRandomSeed</code>\n</li><li><code>CsmJobKeyDerive</code>\n</li><li><code>CsmJobKeyGenerate</code>\n</li><li><code>CsmJobKeyExchangeCalcPubVal</code>\n</li><li><code>CsmJobKeyExchangeCalcSecret</code>\n</li><li><code>CsmJobCertificateParse</code>\n</li><li><code>CsmJobCertificateVerify</code>\n</li></ul>\n</li></ul>"}]};
